const coinGeckoCase = publicCalls.examples.find(item => item.operation_id === 'coingecko.coins_markets');
const turnoverContract = signalContracts.signals.find(item => item.signal_key === 'coingecko_market_turnover_candidate');
const scoreCase = (index, language) => {
  const zh = language === 'zh-CN';
  const selected = identityPilot.cases[index];
  const policy = identityPilot.initial_score_policy;
  const assetId = selected.create_result.asset_id;
  const decisionRef = policy.decision_ref_template.replace('{asset_id}', assetId);
  const eventRows = [
    ['asset_id', assetId], ['asset_name', selected.create_result.asset_name],
    ['event_key', zh ? '待 #3006 按 asset_id + score_key + decision_ref 稳定生成' : 'To be generated by #3006 from asset_id + score_key + decision_ref'],
    ['score_key', policy.input_score_key],
    ['decision_ref', decisionRef],
    ['score_delta', `+${policy.score_delta}`],
    ['created_at', zh ? '待 #3006 首次接受事件时写入 UTC 时间' : 'UTC time to be set by #3006 on first acceptance'],
    ['decay_policy_ref', policy.decay_policy_ref],
    ['half_life_minutes', policy.decay.half_life_minutes],
  ];
  const topicRows = eventRows;
  return { selected, policy, assetId, decisionRef, eventRows, topicRows, cacheRows: topicRows };
};

function CasePicker({ value, setValue, language, label }) {
  return <label className="source-case-inspector-picker">{label}<select value={value} onChange={event => setValue(Number(event.target.value))}>
    {identityPilot.cases.map((item, index) => <option value={index} key={item.source_record.id}>
      {index + 1} · {item.source_record.name} · @{item.source_record.username}</option>)}
  </select></label>;
}

function CaseRows({ rows }) {
  return <dl className="source-case-inspector-fields">{rows.map(([name, value], index) => <div key={name}>
    <dt><span className="source-case-field-number">{String(index + 1).padStart(2, '0')}</span><code>{name}</code></dt>
    <dd>{typeof value === 'string' && value.startsWith('https://') ? <a href={value} target="_blank" rel="noopener noreferrer">{value}</a> : displayCaseValue(value)}</dd>
  </div>)}</dl>;
}

function ScoreTopicHeaders() {
  return <p className="processing-io-case-caption">Headers · {scoreTopicProposal.headers.map((header, index) => <React.Fragment key={header.name}>{index > 0 && ' · '}<code>{header.name}</code> = <code>{header.value}</code></React.Fragment>)}</p>;
}

export function NodeCaseExplanation({ language, purpose, caseSummary, recordGuide, kind = 'node' }) {
  const zh = language === 'zh-CN';
  return <section className="source-case-inspector-explanation node-case-explanation">
    <h3>{zh ? kind === 'table' ? '这张表卡做什么' : '这张节点卡做什么' : kind === 'table' ? 'What this table does' : 'What this node does'}</h3>
    <p>{purpose || (zh ? '这一步的目的尚未说明。' : 'The purpose of this step has not been described.')}</p>
    <h3>{zh ? kind === 'table' ? '目前有哪些记录' : '这次处理到了哪一步' : kind === 'table' ? 'What records exist' : 'What this case shows'}</h3>
    <p>{caseSummary}</p>
    <h3>{zh ? kind === 'table' ? '表记录怎么读' : '所选记录怎么读' : 'How to read the selected record'}</h3>
    <p>{recordGuide}</p>
  </section>;
}

