export function ProcessingIOCard(props) {
  const { node } = props;
  const content = <ProcessingCardContent key={node.id} {...props} />;
  if (['Redpanda Topic', 'Redis Window'].includes(node.type) || node.name === scoreRollup.node.name) return content;
  return <ProcessingCardFrame {...props}>{content}</ProcessingCardFrame>;
}

function ProcessingCardContent({ node, graph, openNode, language, nodeLabel, purpose }) {
  if (node.type === 'Redpanda Topic') {
    return <RedpandaTopicCard node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if (node.type === 'Redis Window') {
    return <RedisWindowCard node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if (node.name === scoreRollup.node.name) {
    return <ScoreRollupCard node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if ([3007, 3008].includes(node.reference_number)) {
    return <ScoreEventConsumerCard node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if ([3003, 4002, 4003].includes(node.reference_number)) {
    return <AssetReviewCase node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if (node.reference_number === 3001) {
    return <MarketTurnoverCaseCard node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if (node.reference_number === identityPilot.initial_score_policy.processing_card) {
    return <InitialScoreCard node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if (node.reference_number === 3006) {
    return <ScoreEventPublisherCard node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if (node.type === 'Flow Result' && node.reference_number === IDENTITY_REFS.matched) {
    return <MatchedIdentityResult node={node} graph={graph} openNode={openNode} language={language} />;
  }
  if (node.reference_number === IDENTITY_REFS.lookup || node.reference_number === IDENTITY_REFS.create) {
    return <IdentityPilotStep node={node} graph={graph} openNode={openNode} language={language} purpose={purpose} />;
  }
  const zh = language === 'zh-CN';
  const incoming = graph.edges.filter(edge => edge.downstream_id === node.id)
    .sort((a, b) => (a.reference_number ?? Infinity) - (b.reference_number ?? Infinity));
  const fields = graph.fields.filter(field => field.node_id === node.id).sort((a, b) => a.ordinal - b.ordinal);
  const fieldById = new Map(graph.fields.map(field => [field.id, field]));
  const inputs = incoming.map(edge => {
    const source = graph.nodes.find(item => item.id === edge.upstream_id);
    const producerEdge = source?.type === 'Redpanda Topic' ? graph.edges.find(item => item.downstream_id === source.id) : null;
    const origin = producerEdge ? graph.nodes.find(item => item.id === producerEdge.upstream_id) : source;
    const usages = graph.field_usages.filter(usage => usage.edge_id === edge.id);
    return { edge, source, origin, isTable: Boolean(source?.is_system_state), fields: usages.map(usage => fieldById.get(usage.source_field_id)).filter(Boolean).sort((a, b) => a.ordinal - b.ordinal) };
  });
  const inputFieldCount = inputs.reduce((count, input) => count + input.fields.length, 0);
  const isSmartFollowing = inputs.some(input => input.origin?.name === SMART_FOLLOWING_OPERATION);
  const [observedCase, setObservedCase] = useState(null);
  const [fieldLabels, setFieldLabels] = useState({});
  useEffect(() => {
    if (!isSmartFollowing) return undefined;
    let active = true;
    fetch(`/api/source-cases/v1/${encodeURIComponent(SMART_FOLLOWING_OPERATION)}`)
      .then(response => response.json())
      .then(data => { if (active) setObservedCase(data.cases?.find(item => item.response_complete && Array.isArray(item.response) && item.response.length)); })
      .catch(() => {});
    fetch(`/api/source-contracts/v1/operations/${encodeURIComponent(SMART_FOLLOWING_OPERATION)}`)
      .then(response => response.json())
      .then(data => { if (active) setFieldLabels(Object.fromEntries((data.operation?.fields || []).map(field => [field.path, field.label_zh]))); })
      .catch(() => {});
    return () => { active = false; };
  }, [isSmartFollowing]);
  const example = observedCase?.response?.[0];
  const exampleFields = new Map(flattenAccount(example));
  const caseRows = fields.map(field => [field.name, exampleFields.get(field.name.replace(/^data\./, ''))]);
  const caseIsComplete = isSmartFollowing && Boolean(example);
  const mappingIsComplete = inputFieldCount > 0 && inputs.filter(input => input.origin?.name === SMART_FOLLOWING_OPERATION).every(input => input.fields.length > 0 && input.fields.every(field => exampleFields.has(field.name.replace(/^data\./, ''))));
  const caseLabel = example ? `${example.name || example.username || example.id} · ${observedCase.response.length} ${zh ? '条上游返回中的第 1 条' : 'upstream rows, first shown'}` : null;
  const caseField = ([path, value], index) => <div key={path}><dt><span className="source-case-field-number">{String(index + 1).padStart(2, '0')}</span>{zh && (fieldLabels[path] || (path === 'asset_id' ? '资产 ID' : path === 'asset_name' ? '资产名称' : path === 'match_status' ? '匹配状态' : ''))} <code>{path}</code></dt><dd>{(path === 'asset_id' || path === 'asset_name' || path === 'match_status') && value === undefined ? zh ? '未知（尚未查表，非实际结果）' : 'Unknown (no table lookup; not an observed result)' : typeof value === 'string' && /^https:\/\//.test(value) ? <a href={value} target="_blank" rel="noopener noreferrer">{value}</a> : displayCaseValue(value)}</dd></div>;
  if (caseIsComplete) return <><div className="source-case-inspector processing-io-case" aria-label={zh ? '输入与输出' : 'Input and output'}>
    <section className="source-case-inspector-section"><div className="source-case-inspector-heading"><h3>{zh ? '输入' : 'Input'}</h3><span>{inputs.length} {zh ? '个来源' : 'sources'}</span></div>
      {inputs.map(({ edge, source, origin, isTable, fields: inputFields }) => {
        const sourceName = nodeLabel?.(source?.name) || displayCatalogNodeName(source, language) || displayNodeName(language, source?.name || '');
        const isObservedSource = origin?.name === SMART_FOLLOWING_OPERATION;
        const isIdentifierTable = isTable && source?.name === 'asset_identifiers';
        return <div className="processing-input-source" key={edge.id}>
          <div className="processing-input-source-heading"><span>{zh ? '来自' : 'From'}</span><button onClick={() => source && openNode(source.id)}>{nodeRef(source)} {sourceName}</button></div>
          {isObservedSource ? <><p className="processing-io-case-caption">{caseLabel} · {zh ? '真实上游返回；#4001 尚无实际消费记录。' : 'Observed upstream response; #4001 has no observed consumed record.'}</p>
            <dl className="source-case-inspector-fields">{inputFields.map(field => [field.name, exampleFields.get(field.name.replace(/^data\./, ''))]).map(caseField)}</dl></>
            : isIdentifierTable ? <><p className="processing-io-case-caption">{zh ? '规划读取 asset_identifiers；查询方式和真实表行仍待确认。' : 'Planned asset_identifiers read; lookup method and actual table rows remain unverified.'}</p>
              <dl className="source-case-inspector-fields">
                <div><dt><span className="source-case-field-number">01</span>{zh ? '候选查询值' : 'Candidate lookup value'} <code>data.id</code></dt><dd>{displayCaseValue(example.id)}</dd></div>
                <div><dt><span className="source-case-field-number">02</span>{zh ? '目标字段' : 'Target field'} <code>asset_id</code></dt><dd>{zh ? '未知（尚无表结果）' : 'Unknown (no table result)'}</dd></div>
              </dl></>
              : <><p className="processing-io-case-caption">{isTable ? zh ? '规划读表；尚无实际表行或查询结果。' : 'Planned table read; no observed row or query result.' : zh ? '此路尚无配对的真实输入案例。' : 'No paired observed input case for this source.'}</p>
                {inputFields.length > 0 && <dl className="source-case-inspector-fields">{inputFields.map((field, fieldIndex) => <div key={field.id}><dt><span className="source-case-field-number">{String(fieldIndex + 1).padStart(2, '0')}</span><code>{field.name}</code></dt><dd>{zh ? '待核对' : 'Unverified'}</dd></div>)}</dl>}
                {isTable && edge.transformation && <p className="processing-io-case-note">{edge.transformation}</p>}
              </>}
        </div>;
      })}
    </section>
    <section className="source-case-inspector-section"><div className="source-case-inspector-heading"><h3>{zh ? '输出' : 'Output'}</h3><span>{caseRows.length} {zh ? '个字段 · 规则示意' : 'fields · illustration'}</span></div>
      <p className="processing-io-case-caption">{zh ? '输出结构示意：仅列本步骤声明的输出字段。精确匹配到已有资产时才填 asset_id；当前没有实际查表结果。' : 'Output illustration: only fields declared by this step are listed. Fill asset_id only after an exact existing-asset match; no table result is observed.'}</p>
      <dl className="source-case-inspector-fields">{caseRows.map(caseField)}</dl>
      {!mappingIsComplete && <p className="processing-io-case-note">{zh ? '当前案例字段与图中的字段映射数量不一致；请检查消息与 #4001 定义。' : 'The case fields and saved graph mappings differ; review the message and #4001 definition.'}</p>}
    </section>
  </div><NodeCaseExplanation language={language} purpose={purpose || node.definition}
    caseSummary={zh ? `这里展示 #2030 返回的第 1 条账号记录（${example.name || example.username || example.id}）。#4001 尚无实际消费、查表或处理结果；右侧输出只是结构示意。` : `The first #2030 account row (${example.name || example.username || example.id}) is shown. #4001 has no observed consumption, table lookup, or processed result; the output is a shape illustration.`}
    recordGuide={zh ? '仅展示声明的输入与输出字段；完整账号记录请到来源卡片查看。当前没有实际匹配结果。' : 'Only declared input and output fields are shown; open the source card for the full account. No actual match has been observed.'} /></>;
  const plannedValue = field => field.example_value || (zh ? '尚无实际处理结果' : 'No observed processed result');
  return <><div className="source-case-inspector processing-io-case" aria-label={zh ? '输入与输出' : 'Input and output'}>
    <section className="source-case-inspector-section"><div className="source-case-inspector-heading"><h3>{zh ? '输入' : 'Input'}</h3><span>{inputs.length} {zh ? '个来源' : 'sources'}</span></div>
      {inputs.map(({ edge, source, isTable, fields: inputFields }) => <div className="processing-input-source" key={edge.id}>
        <div className="processing-input-source-heading"><span>{zh ? '来自' : 'From'}</span><button onClick={() => source && openNode(source.id)}>{nodeRef(source)} {nodeLabel?.(source?.name) || displayCatalogNodeName(source, language) || displayNodeName(language, source?.name || '')}</button></div>
        <p className="processing-io-case-caption">{isTable ? zh ? '规划读表；尚无实际表行或查询结果。' : 'Planned table read; no observed row or query result.' : zh ? '此来源尚无配对的真实处理结果。' : 'No paired observed processed result from this source.'}</p>
        {inputFields.length > 0 ? <dl className="source-case-inspector-fields">{inputFields.map((field, index) => <div key={field.id}><dt><span className="source-case-field-number">{String(index + 1).padStart(2, '0')}</span><code>{field.name}</code></dt><dd>{plannedValue(field)}</dd></div>)}</dl>
          : <p className="processing-io-case-note">{edge.rationale || (zh ? '这一路尚未定义输入字段。' : 'No input fields have been defined for this source.')}</p>}
        {isTable && inputFields.length > 0 && edge.rationale && <p className="processing-io-case-note">{edge.rationale}</p>}
      </div>)}
      {inputs.length === 0 && <p className="processing-io-case-caption">{zh ? '尚未连接输入。' : 'No input connected.'}</p>}
    </section>
    <section className="source-case-inspector-section"><div className="source-case-inspector-heading"><h3>{zh ? '输出' : 'Output'}</h3><span>{fields.length} {zh ? '个字段 · 规划示意' : 'fields · illustration'}</span></div>
      <p className="processing-io-case-caption">{zh ? '字段值用于展示预期格式，尚无这一步的真实处理结果。' : 'Values illustrate the expected format; no processed result is observed.'}</p>
      {fields.length > 0 ? <dl className="source-case-inspector-fields">{fields.map((field, index) => <div key={field.id}><dt><span className="source-case-field-number">{String(index + 1).padStart(2, '0')}</span><code>{field.name}</code></dt><dd>{plannedValue(field)}</dd></div>)}</dl>
        : <p className="processing-io-case-caption">{zh ? '尚未定义输出字段。' : 'No output fields defined.'}</p>}
    </section>
  </div><NodeCaseExplanation language={language} purpose={purpose || node.definition}
    caseSummary={zh ? '目前只有输入与输出字段设计，尚无这张节点卡的实际处理案例。' : 'Only input and output fields are designed; no processed case is available for this node.'}
    recordGuide={zh ? '尚无成对的真实输入和处理结果，暂时不能解读某条输出记录。' : 'There is no paired real input and processed result to interpret yet.'} /></>;
}
